                writeln!(handle, "{json_string}").expect("failed to print");
            } else {
                workspaces.iter().for_each(|workspace| {
                    writeln!(handle, "{workspace}").expect("failed to print")
                });
            }
            return Ok(());
        }

        if let Some(Entity::Task {
            json: entity_json,
