            } else {
                tasks
                    .iter()
                    .for_each(|task| writeln!(handle, "{task}").expect("failed to print"));
            }
            return Ok(());
        }

        match api_client.get_entities().await {
            Err(error) => {
                return Err(error);
            }
            Ok(entities) => {
                // use this to avoid calling println! in a loop:
