{"path":"/home/user/workspace/src/commands/bill.rs","old":"    #[test]
    fn ignores_non_billable_running_and_non_positive_entries() {","new":"    #[test]
    fn json_output_uses_snake_case_keys_and_preserves_order() {
        let output = BillJson {
            projects: aggregate_billable_entries(&[
                entry(22 * 60, true, Some(1_700_000_100), Some("Beta")),
                entry(7 * 60, true, Some(1_700_000_100), Some("Alpha")),
            ])
            .into_iter()
            .map(|(project, billable_seconds)| BillJsonProject {
                project,
                billable_seconds,
            })
            .collect(),
            total_billable_seconds: 3_600,
        };

        assert_eq!(
            serde_json::to_string(&output).unwrap(),
            r#"{"projects":[{"project":"Beta","billable_seconds":1800},{"project":"Alpha","billable_seconds":900}],"total_billable_seconds":3600}"#
        );
    }

    #[test]
    fn empty_json_output_has_zero_total() {
        let output = BillJson {
            projects: Vec::new(),
            total_billable_seconds: 0,
        };
        assert_eq!(
            serde_json::to_string(&output).unwrap(),
            r#"{"projects":[],"total_billable_seconds":0}"#
        );
    }

    #[test]
    fn ignores_non_billable_running_and_non_positive_entries() {"}

